//! \file
//! \brief A set of utility tools to deal with unbounded strings.
#pragma once

#include "../Defines.h"
#include "TypeTraits.h"

namespace carb::cpp
{
//! Helper variable template for the value member of the \ref is_unbounded_character_sequence template.
template <class T, class CharT>
constexpr bool is_unbounded_character_sequence_v = (std::is_pointer_v<T> ||
                                                    is_unbounded_array_v<T>)&&std::is_convertible_v<T, const CharT*>;

//! Checks whether T is an unbounded basic string.
template <class T, class CharT>
struct is_unbounded_character_sequence : std::bool_constant<is_unbounded_character_sequence_v<T, CharT>>
{
};

/**
 * A class that represents an unbounded string.
 * This class is used to represent an unbounded string (i.e. a character pointer to a null-terminated string).
 * The difference between this class and `const char*` is that this class will not be constructed from pointer decays
 * (e.g. char[N]).
 * @tparam TChar The character type.
 */
template <typename CharT>
class CARB_VIZ basic_unbounded_string
{
    const CharT* m_ptr;

public:
    //! `CharT`
    using value_type = CharT;
    //! `CharT*`
    using pointer = CharT*;
    //! `const CharT*`
    using const_pointer = const CharT*;
    //! `std::size_t`
    using size_type = std::size_t;

    /**
     * Default constructor.
     */
    constexpr basic_unbounded_string() noexcept : m_ptr(nullptr)
    {
    }

    /**
     * Constructor from a character sequence.
     * @tparam T The character sequence type.
     * @param ptr The character sequence.
     * @note Due to a bug, in GCC this constructor sometimes is triggered with char[N]
     */
    template <typename T, std::enable_if_t<is_unbounded_character_sequence_v<remove_cvref_t<T>, value_type>, bool> = true>
    constexpr basic_unbounded_string(T&& ptr) noexcept : m_ptr(ptr)
    {
    }

    /**
     * Conversion operator to a character pointer.
     * @returns The character pointer.
     */
    constexpr operator const_pointer() const noexcept
    {
        return m_ptr;
    }

    /**
     * Returns a pointer to the first character of a view.
     * @returns A pointer to the first character of the view.
     */
    constexpr const_pointer data() const noexcept
    {
        return m_ptr;
    }
};

//! basic_unbounded_string<char>
//! @see basic_unbounded_string
using unbounded_string = basic_unbounded_string<char>;

//! basic_unbounded_string<wchar_t>
//! @see basic_unbounded_string
using unbounded_wstring = basic_unbounded_string<wchar_t>;

#if CARB_HAS_CPP20 && defined(__cpp_char8_t)
//! basic_unbounded_string<char8_t>
//! @see basic_unbounded_string
using unbounded_u8string = basic_unbounded_string<char8_t>;
#endif

//! basic_unbounded_string<char16_t>
//! @see basic_string_view
using unbounded_u16string = basic_unbounded_string<char16_t>;
//! basic_unbounded_string<char32_t>
//! @see basic_unbounded_string
using unbounded_u32string = basic_unbounded_string<char32_t>;

} // namespace carb::cpp
